<script>
  (function() {
    const root = document.documentElement;
    const svg = document.getElementById('svg');
    const treeType = document.getElementById('treeType');
    const prevBtn = document.getElementById('prev');
    const nextBtn = document.getElementById('next');
    const resetBtn = document.getElementById('reset');
    const inorderSpan = document.getElementById('inorder');
    const statusSpan = document.getElementById('status');

    // state_model
    let step = 1; // 0=仅失衡树, 1=双树+标注, 2=双树+高亮移动
    let type = 'LL';

    // 纯函数：根据 type 和 step 计算节点坐标、连线、标注可见性
    function computeState(t, s) {
      const isLL = t === 'LL';
      // 左侧树：失衡链
      const left = {
        nodes: isLL
          ? [{x:170,y:80,val:30},{x:170,y:140,val:20},{x:170,y:200,val:10}]
          : [{x:170,y:80,val:10},{x:170,y:140,val:20},{x:170,y:200,val:30}],
        lines: isLL
          ? [{x1:170,y1:80,x2:170,y2:140},{x1:170,y1:140,x2:170,y2:200}]
          : [{x1:170,y1:80,x2:170,y2:140},{x1:170,y1:140,x2:170,y2:200}],
        boxes: isLL
          ? [{x:120,y:222,w:100,h:40,label:'α'},{x:120,y:162,w:100,h:40,label:'β'},{x:120,y:102,w:100,h:40,label:'γ'}]
          : [{x:120,y:222,w:100,h:40,label:'α'},{x:120,y:162,w:100,h:40,label:'β'},{x:120,y:102,w:100,h:40,label:'γ'}]
      };
      // 右侧树：旋转后
      const right = {
        nodes: [
          {x:510,y:80,val:20},
          {x:440,y:140,val:10},
          {x:580,y:140,val:30}
        ],
        lines: [
          {x1:510,y1:80,x2:440,y2:140},
          {x1:510,y1:80,x2:580,y2:140}
        ],
        boxes: isLL
          ? [{x:390,y:162,w:100,h:40,label:'α'},{x:390,y:102,w:100,h:40,label:'β'},{x:530,y:162,w:100,h:40,label:'γ'}]
          : [{x:390,y:162,w:100,h:40,label:'α'},{x:390,y:102,w:100,h:40,label:'β'},{x:530,y:162,w:100,h:40,label:'γ'}]
      };
      // 箭头：从左侧子树中心指向右侧子树中心
      const arrows = isLL
        ? [{x1:170,y1:242,x2:440,y2:182},{x1:170,y1:182,x2:440,y2:122},{x1:170,y1:122,x2:580,y2:182}]
        : [{x1:170,y1:242,x2:440,y2:182},{x1:170,y1:182,x2:440,y2:122},{x1:170,y1:122,x2:580,y2:182}];
      // 可见性
      const showLeft = s >= 0;
      const showRight = s >= 1;
      const showArrows = s >= 2;
      const balanced = s >= 1;
      return { left, right, arrows, showLeft, showRight, showArrows, balanced };
    }

    function update() {
      const state = computeState(type, step);
      // 左侧树
      const leftG = document.getElementById('leftTree');
      leftG.style.display = state.showLeft ? '' : 'none';
      if (state.showLeft) {
        for (let i = 0; i < 3; i++) {
          const n = state.left.nodes[i];
          document.getElementById('ln'+(i+1)).setAttribute('cx', n.x);
          document.getElementById('ln'+(i+1)).setAttribute('cy', n.y);
          document.getElementById('lt'+(i+1)).setAttribute('x', n.x);
          document.getElementById('lt'+(i+1)).setAttribute('y', n.y);
          document.getElementById('lt'+(i+1)).textContent = n.val;
        }
        for (let i = 0; i < 2; i++) {
          const l = state.left.lines[i];
          document.getElementById('l'+(i+1)).setAttribute('x1', l.x1);
          document.getElementById('l'+(i+1)).setAttribute('y1', l.y1);
          document.getElementById('l'+(i+1)).setAttribute('x2', l.x2);
          document.getElementById('l'+(i+1)).setAttribute('y2', l.y2);
        }
        for (let i = 0; i < 3; i++) {
          const b = state.left.boxes[i];
          const box = document.getElementById('lbox' + String.fromCharCode(65+i));
          const lab = document.getElementById('lbox' + String.fromCharCode(65+i) + '_label');
          box.setAttribute('x', b.x);
          box.setAttribute('y', b.y);
          box.setAttribute('width', b.w);
          box.setAttribute('height', b.h);
          lab.setAttribute('x', b.x + b.w/2);
          lab.setAttribute('y', b.y + b.h/2);
          lab.textContent = b.label;
        }
      }
      // 右侧树
      const rightG = document.getElementById('rightTree');
      rightG.style.display = state.showRight ? '' : 'none';
      if (state.showRight) {
        for (let i = 0; i < 3; i++) {
          const n = state.right.nodes[i];
          document.getElementById('rn'+(i+1)).setAttribute('cx', n.x);
          document.getElementById('rn'+(i+1)).setAttribute('cy', n.y);
          document.getElementById('rt'+(i+1)).setAttribute('x', n.x);
          document.getElementById('rt'+(i+1)).setAttribute('y', n.y);
          document.getElementById('rt'+(i+1)).textContent = n.val;
        }
        for (let i = 0; i < 2; i++) {
          const l = state.right.lines[i];
          document.getElementById('r'+(i+1)).setAttribute('x1', l.x1);
          document.getElementById('r'+(i+1)).setAttribute('y1', l.y1);
          document.getElementById('r'+(i+1)).setAttribute('x2', l.x2);
          document.getElementById('r'+(i+1)).setAttribute('y2', l.y2);
        }
        for (let i = 0; i < 3; i++) {
          const b = state.right.boxes[i];
          const box = document.getElementById('rbox' + String.fromCharCode(65+i));
          const lab = document.getElementById('rbox' + String.fromCharCode(65+i) + '_label');
          box.setAttribute('x', b.x);
          box.setAttribute('y', b.y);
          box.setAttribute('width', b.w);
          box.setAttribute('height', b.h);
          lab.setAttribute('x', b.x + b.w/2);
          lab.setAttribute('y', b.y + b.h/2);
          lab.textContent = b.label;
        }
        // 箭头
        for (let i = 0; i < 3; i++) {
          const a = state.arrows[i];
          const arrowEl = document.getElementById('arrow' + String.fromCharCode(65+i));
          arrowEl.setAttribute('d', 'M ' + a.x1 + ' ' + a.y1 + ' L ' + a.x2 + ' ' + a.y2);
          arrowEl.setAttribute('opacity', state.showArrows ? '0.7' : '0');
          if (state.showArrows) {
            arrowEl.classList.add('highlight');
          } else {
            arrowEl.classList.remove('highlight');
          }
        }
      }
      // 中序遍历不变
      inorderSpan.textContent = '10, 20, 30';
      // 平衡状态
      if (state.balanced) {
        statusSpan.textContent = '已平衡';
        statusSpan.className = 'balanced';
      } else {
        statusSpan.textContent = '失衡';
        statusSpan.className = 'unbalanced';
      }
    }

    // 交互事件
    prevBtn.addEventListener('click', function() {
      step = Math.max(0, step - 1);
      update();
    });
    nextBtn.addEventListener('click', function() {
      step = Math.min(2, step + 1);
      update();
    });
    resetBtn.addEventListener('click', function() {
      step = 0;
      update();
    });
    treeType.addEventListener('change', function() {
      type = this.value;
      step = 0;
      update();
    });

    // 初始渲染：step=1, type='LL'
    update();

    // verification_cases
    (function verify() {
      // case 1: step=0, LL
      let s = computeState('LL', 0);
      console.assert(s.showLeft === true, 'step0: left visible');
      console.assert(s.showRight === false, 'step0: right hidden');
      console.assert(s.balanced === false, 'step0: unbalanced');
      // case 2: step=1, LL
      s = computeState('LL', 1);
      console.assert(s.showLeft === true, 'step1: left visible');
      console.assert(s.showRight === true, 'step1: right visible');
      console.assert(s.showArrows === false, 'step1: arrows hidden');
      console.assert(s.balanced === true, 'step1: balanced');
      // case 3: step=2, LL
      s = computeState('LL', 2);
      console.assert(s.showArrows === true, 'step2: arrows visible');
      // case 4: step=0, RR
      s = computeState('RR', 0);
      console.assert(s.showLeft === true, 'RR step0: left visible');
      console.assert(s.showRight === false, 'RR step0: right hidden');
      console.assert(s.balanced === false, 'RR step0: unbalanced');
      // case 5: step=1, RR
      s = computeState('RR', 1);
      console.assert(s.showRight === true, 'RR step1: right visible');
      console.assert(s.balanced === true, 'RR step1: balanced');
      console.log('All verification cases passed');
    })();
  })();
</script>
